//! Minimal stand-in for the VSS uProtocol publisher: publishes a battery
//! temperature profile on the Guardian's input topic, optionally with one
//! deterministic fault injected in a time window. Meant for local testing of
//! the Guardian, not as a replacement for the fault campaign runner.
//!
//! Where it sits: it replaces the left half of the real chain
//! (AZ3166 -> Mosquitto -> vss-uprotocol-publisher) and talks to the Guardian
//! directly over uProtocol/Zenoh, with the same `VssSample` payload.
//!
//! Example: `vss-sim overheat -c config/demo.toml --correlation-id run-001`

use std::str::FromStr;
use std::time::Duration;

use clap::{Parser, ValueEnum};
use guardian::config::GuardianConfig;
use guardian::contract::VssSample;
use guardian::transport;
use tracing::info;
use up_rust::{
    LocalUriProvider, StaticUriProvider, UMessage, UMessageBuilder, UPayloadFormat, UTransport,
    UUri,
};

/// What to simulate. Temperature profiles change the value over time; fault
/// scenarios use the nominal ~30 C profile and break it between
/// `--fault-start-s` and `--fault-end-s`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
enum Scenario {
    /// Stable ~30 C.
    Nominal,
    /// Ramp to 72 C, hold, cool down: WARNING -> CRITICAL -> MITIGATING -> MONITORING.
    Overheat,
    /// Ramp to 72 C and keep rising: mitigation fails and escalates.
    Runaway,
    /// Value frozen during the fault window.
    Stuck,
    /// Single-sample +40 C spikes during the fault window.
    Spike,
    /// 200 C during the fault window.
    OutOfRange,
    /// Nothing published during the fault window.
    Dropout,
    /// Samples delivered 2 s late during the fault window.
    Delay,
    /// Every sample sent twice during the fault window.
    Duplicate,
    /// Consecutive samples swapped during the fault window.
    Reorder,
}

#[derive(Parser)]
struct Args {
    #[arg(value_enum)]
    scenario: Scenario,
    /// Guardian configuration (TOML) providing authority, input topic and VSS path.
    #[arg(short, long)]
    config: Option<std::path::PathBuf>,
    #[arg(long)]
    zenoh_config: Option<String>,
    /// Samples per second.
    #[arg(long, default_value_t = 2.0)]
    rate_hz: f64,
    #[arg(long, default_value_t = 90.0)]
    duration_s: f64,
    #[arg(long, default_value_t = 10.0)]
    fault_start_s: f64,
    #[arg(long, default_value_t = 25.0)]
    fault_end_s: f64,
    /// Correlation ID put into every sample (e.g. campaign run ID).
    #[arg(long)]
    correlation_id: Option<String>,
}

/// How late samples are delivered in the `delay` scenario.
const DELAY_MS: u64 = 2000;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    transport::init_logging();
    let args = Args::parse();
    // Same config file as the Guardian, so both agree on topic and VSS path.
    let cfg = match &args.config {
        Some(path) => GuardianConfig::load(path)?,
        None => GuardianConfig::default(),
    };
    let up = &cfg.uprotocol;

    // The Guardian's input filter (e.g. //*/8001/1/8001) tells us which topic
    // to publish on: same entity, version and resource, but our own authority
    // instead of the wildcard.
    let filter = UUri::from_str(&up.input_topic)?;
    if filter.has_wildcard_entity_type() || filter.has_wildcard_resource_id() {
        return Err("input_topic must name a concrete entity and resource".into());
    }
    let topic = StaticUriProvider::new(
        up.authority.clone(),
        filter.ue_id,
        filter.uentity_major_version(),
    )
    .get_resource_uri(filter.resource_id());

    let zenoh_config = args.zenoh_config.as_deref().or(up.zenoh_config.as_deref());
    let transport = transport::zenoh_transport(&up.authority, zenoh_config).await?;
    info!(topic = %topic.to_uri(false), scenario = ?args.scenario, "publishing");

    let period = Duration::from_secs_f64(1.0 / args.rate_hz);
    let mut interval = tokio::time::interval(period);
    let mut seq = 0u64;
    // Stuck scenario: the value at the start of the fault window.
    let mut frozen: Option<f64> = None;
    // Reorder scenario: a message held back to be sent after the next one.
    let mut held_back: Option<UMessage> = None;

    // One iteration per sample period; `t` = seconds since start.
    for i in 0.. {
        interval.tick().await;
        let t = i as f64 / args.rate_hz;
        if t >= args.duration_s {
            break;
        }
        let in_fault = t >= args.fault_start_s && t < args.fault_end_s;
        let mut value = base_temperature(args.scenario, t);

        // Faults that change the *value* (or suppress the sample entirely).
        if in_fault {
            match args.scenario {
                Scenario::Dropout => continue,
                Scenario::Stuck => value = *frozen.get_or_insert(value),
                Scenario::Spike if i % 4 == 0 => value += 40.0,
                Scenario::OutOfRange => value = 200.0,
                _ => {}
            }
        }

        seq += 1;
        let sample = VssSample {
            path: up.vss_path.clone(),
            value: (value * 10.0).round() / 10.0, // 0.1 C resolution, like a real sensor
            seq,
            rolling_counter: Some(seq % 256), // mimics an 8-bit device counter
            correlation_id: args.correlation_id.clone(),
        };
        info!(seq, value = sample.value, in_fault, "sample");
        // Build the uMessage now: its id records this moment as the sample
        // time, even if the message is sent later (delay / reorder).
        let msg = match build_message(&topic, &sample) {
            Ok(m) => m,
            Err(e) => {
                tracing::warn!("cannot build message: {e}");
                continue;
            }
        };

        // Faults that change the *delivery*: what to send now, and in which order.
        let mut batch = vec![msg];
        if in_fault {
            match args.scenario {
                // Same message twice -> Guardian sees the same seq twice.
                Scenario::Duplicate => batch.push(batch[0].clone()),
                // Hold one message back, send it after the next one.
                Scenario::Reorder => match held_back.take() {
                    Some(older) => batch.push(older),
                    None => {
                        held_back = batch.pop();
                        continue;
                    }
                },
                // Send from a separate task after DELAY_MS. The message keeps
                // its creation time -> Guardian measures the latency.
                Scenario::Delay => {
                    let (transport, msg) = (transport.clone(), batch.remove(0));
                    tokio::spawn(async move {
                        tokio::time::sleep(Duration::from_millis(DELAY_MS)).await;
                        send(&*transport, msg).await;
                    });
                }
                _ => {}
            }
        }
        for msg in batch {
            send(&*transport, msg).await;
        }
    }
    // Let delayed samples go out before the session closes.
    tokio::time::sleep(Duration::from_millis(DELAY_MS + 200)).await;
    Ok(())
}

/// Temperature at time `t` (s) for the scenario, as (time, value) waypoints
/// with straight lines in between.
fn base_temperature(scenario: Scenario, t: f64) -> f64 {
    let profile: &[(f64, f64)] = match scenario {
        Scenario::Overheat => &[
            (0.0, 30.0),
            (10.0, 30.0),
            (40.0, 72.0),
            (55.0, 72.0),
            (80.0, 35.0),
        ],
        Scenario::Runaway => &[(0.0, 30.0), (10.0, 30.0), (40.0, 72.0), (300.0, 100.0)],
        _ => &[(0.0, 30.0)],
    };
    // Small deterministic ripple, so a healthy signal is never "stuck".
    interpolate(profile, t) + 0.3 * (t * 0.9).sin()
}

/// Linear interpolation between waypoints; after the last one, its value.
fn interpolate(points: &[(f64, f64)], t: f64) -> f64 {
    for w in points.windows(2) {
        let ((t0, v0), (t1, v1)) = (w[0], w[1]);
        if t < t1 {
            return v0 + (v1 - v0) * ((t - t0) / (t1 - t0)).clamp(0.0, 1.0);
        }
    }
    points.last().map(|p| p.1).unwrap_or(0.0)
}

/// One sample as a JSON PUBLISH uMessage (same format as the real publisher).
/// The builder gives it a new UUIDv7 id that records the current time.
fn build_message(topic: &UUri, sample: &VssSample) -> Result<UMessage, String> {
    let payload = serde_json::to_vec(sample).map_err(|e| e.to_string())?;
    UMessageBuilder::publish(topic.clone())
        .build_with_payload(payload, UPayloadFormat::UPAYLOAD_FORMAT_JSON)
        .map_err(|e| e.to_string())
}

async fn send(transport: &dyn UTransport, msg: UMessage) {
    if let Err(e) = transport.send(msg).await {
        tracing::warn!("publish failed: {e}");
    }
}
